{"protocolSection":{"identificationModule":{"nctId":"NCT07357948","orgStudyIdInfo":{"id":"IC 2025-05"},"secondaryIdInfos":[{"id":"2025-A02926-43","type":"OTHER","domain":"ANSM"}],"organization":{"fullName":"Institut Curie","class":"OTHER"},"briefTitle":"Omission of Surgery for Triple-negative Breast Cancer in Complete Response After Neoadjuvant Chemo-immunotherapy","officialTitle":"Omission of Surgery for Triple-negative Breast Cancer in Complete Response Confirmed by MRI and Macrobiopsy After Neoadjuvant Chemo-immunotherapy: a Randomized, Multicenter Phase II Trial.","acronym":"OMICHIR"},"statusModule":{"statusVerifiedDate":"2026-01","overallStatus":"NOT_YET_RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2026-08-01","type":"ESTIMATED"},"primaryCompletionDateStruct":{"date":"2031-07-31","type":"ESTIMATED"},"completionDateStruct":{"date":"2033-07-31","type":"ESTIMATED"},"studyFirstSubmitDate":"2026-01-05","studyFirstSubmitQcDate":"2026-01-13","studyFirstPostDateStruct":{"date":"2026-01-22","type":"ACTUAL"},"lastUpdateSubmitDate":"2026-06-01","lastUpdatePostDateStruct":{"date":"2026-06-03","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Institut Curie","class":"OTHER"}},"oversightModule":{"oversightHasDmc":true,"isFdaRegulatedDrug":false,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"This clinical study aims to determine if skipping breast and axillary surgery could provide similar control of local and distant disease, with fewer complications and better quality of life, for triple-negative breast cancer patients in complete response after neoadjuvant chemo-immunotherapy.

