{"protocolSection":{"identificationModule":{"nctId":"NCT02415387","orgStudyIdInfo":{"id":"OSU-13194"},"secondaryIdInfos":[{"id":"NCI-2014-01251","type":"REGISTRY","domain":"CTRP (Clinical Trial Reporting Program)"}],"organization":{"fullName":"Ohio State University Comprehensive Cancer Center","class":"OTHER"},"briefTitle":"Typhoid Vaccine in Testing Response to Immune Stress in Patients With Stage I-IIIA Breast Cancer","officialTitle":"The IMPACT Study: Inflammatory Responses, Mood and Physical Fitness After Cancer Treatment","acronym":"IMPACT"},"statusModule":{"statusVerifiedDate":"2024-07","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2014-01-01","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2021-04-27","type":"ACTUAL"},"completionDateStruct":{"date":"2021-04-27","type":"ACTUAL"},"studyFirstSubmitDate":"2015-04-09","studyFirstSubmitQcDate":"2015-04-09","studyFirstPostDateStruct":{"date":"2015-04-14","type":"ESTIMATED"},"resultsFirstSubmitDate":"2022-06-06","resultsFirstSubmitQcDate":"2024-07-22","resultsFirstPostDateStruct":{"date":"2024-07-24","type":"ACTUAL"},"lastUpdateSubmitDate":"2024-07-22","lastUpdatePostDateStruct":{"date":"2024-07-24","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"PRINCIPAL_INVESTIGATOR","investigatorFullName":"Janice Kiecolt-Glaser","investigatorTitle":"Principal Investigator","investigatorAffiliation":"Ohio State University Comprehensive Cancer Center"},"leadSponsor":{"name":"Ohio State University Comprehensive Cancer Center","class":"OTHER"}},"oversightModule":{"oversightHasDmc":true,"isFdaRegulatedDrug":true,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"This randomized clinical trial uses an inactive typhoid vaccine to briefly stimulate an immune response in patients with stage I-IIIA breast cancer who received primary cancer treatment and studies whether patients' fitness levels affect how their bodies handle a challenge to their immune system. A vaccine is a substance or group of substances meant to cause the immune system to respond to a tumor or to microorganisms such as bacteria or viruses. Immune responses may cause excess inflammation in the body and behavioral changes, such as depression, fatigue, pain, and problems with thinking and reasoning. Studying immune responses in patients with breast cancer who have undergone primary cancer treatment may help doctors learn whether physical fitness can protect the body from effects of immune system stress and whether it may be able to reduce health problems in patients with breast cancer.","detailedDescription":"PRIMARY OBJECTIVES:

I. To evaluate the relationships between cardiorespiratory fitness and inflammatory and behavioral responses (negative mood, fatigue, pain, and cognitive problems) to typhoid vaccine in breast cancer survivors.

II. To determine the effects of age and depressive symptoms on inflammatory and behavioral responses to typhoid vaccine and placebo.

III. To assess the ability of cardiorespiratory fitness to moderate age- and depression-related responses to typhoid vaccine.

OUTLINE: Patients are randomized to 1 of 2 arms.

ARM I: Patients receive inactive typhoid vaccine intramuscularly (IM) at visit 1 followed by placebo IM 30 days later at visit 2.

ARM II: Patients receive placebo IM at visit 1 followed by inactive typhoid vaccine IM 30 days later at visit 2.

There is an initial screening visit where patients in both arms complete an audio-recorded interview that includes questions about changes in mood and emotion throughout their lives, body measurements, a finger stick to assess for anemia and diabetes markers. During visit 1 and 2, patients in both arms will have blood drawn periodically and complete sets of questionnaires that assess feelings, health behaviors, and personality. Patients also complete cognitive tasks and a temperature sensitivity task at 3-4.5 hours post-injection."},"conditionsModule":{"conditions":["Cognitive Side Effects of Cancer Therapy","Depression","Recurrent Breast Carcinoma","Stage IA Breast Cancer","Stage IB Breast Cancer","Stage IIA Breast Cancer","Stage IIB Breast Cancer","Stage IIIA Breast Cancer"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["EARLY_PHASE1"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"CROSSOVER","primaryPurpose":"BASIC_SCIENCE","maskingInfo":{"masking":"QUADRUPLE","whoMasked":["PARTICIPANT","CARE_PROVIDER","INVESTIGATOR","OUTCOMES_ASSESSOR"]}},"enrollmentInfo":{"count":172,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"Arm I (inactive typhoid vaccine, placebo)","type":"EXPERIMENTAL","description":"Patients receive inactive typhoid vaccine IM at visit 1 followed by placebo IM 30 days later at visit 2.","interventionNames":["Biological: typhoid vaccine","Other: Placebo"]},{"label":"Arm II (placebo, inactive typhoid vaccine)","type":"PLACEBO_COMPARATOR","description":"Patients receive placebo IM at visit 1 followed by inactive typhoid vaccine IM 30 days later at visit 2.","interventionNames":["Biological: typhoid vaccine","Other: Placebo"]}],"interventions":[{"type":"BIOLOGICAL","name":"typhoid vaccine","description":"Given IM","armGroupLabels":["Arm I (inactive typhoid vaccine, placebo)","Arm II (placebo, inactive typhoid vaccine)"]},{"type":"OTHER","name":"Placebo","description":"Given IM","armGroupLabels":["Arm I (inactive typhoid vaccine, placebo)","Arm II (placebo, inactive typhoid vaccine)"],"otherNames":["PLCB"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"AUC Change in Level of IL-6","description":"AUC change refers to the 'net incremental' area, which is the area under the curve above the baseline value. Data points used in AUC change calculation include baseline, 1.5, 3, 5, 6.5, 8 hours post vaccine. This can be calculated geometrically by applying the trapezoid rule. When a value falls below the baseline, only the area above the baseline level is included.","timeFrame":"Baseline, 1.5, 3, 5, 6.5, 8 hours post vaccine"}],"secondaryOutcomes":[{"measure":"AUC Change in Pain","description":"Self-reported intensity of pain on 0-9 scale (0 = no pain; 9 = pain as bad as you can imagine). AUC change refers to the 'net incremental' area, which is the area under the curve above the baseline value. Data points used in AUC change calculation include baseline, 2, 3.5, 5, 6.5, 8.5 hours post vaccine. This can be calculated geometrically by applying the trapezoid rule. When a value falls below the baseline, only the area above the baseline level is included.","timeFrame":"baseline, 2, 3.5, 5, 6.5, 8.5 hours post vaccine"},{"measure":"AUC Change in Fatigue","description":"Self-reported intensity of fatigue on 0-9 scales (0 = no fatigue; 9 = fatigue as bad as you can imagine). AUC change refers to the 'net incremental' area, which is the area under the curve above the baseline value. Data points used in AUC change calculation include baseline, 2, 3.5, 5, 6.5, 8.5 hours post vaccine. This can be calculated geometrically by applying the trapezoid rule. When a value falls below the baseline, only the area above the baseline level is included.","timeFrame":"baseline, 2, 3.5, 5, 6.5, 8.5 hours post vaccine"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Women who have been diagnosed with stage I-IIIA breast cancer will be recruited 1-10 years after the completion of all primary cancer treatment except for longer-term hormonal therapies (tamoxifen, aromatase inhibitors)
* All women will be postmenopausal

Exclusion Criteria:

* A prior history of any other malignancy except basal or squamous cell skin cancers, strokes, diabetes, current heart disease or uncontrolled hypertension, peripheral vascular disease, liver disease, autoimmune and/or inflammatory diseases including rheumatoid arthritis and ulcerative colitis, and other medical conditions that would limit participation in the assessments (e.g., pulmonary disease, orthopedic problems, major psychiatric illness, major cognitive dysfunction, or an acute medical problem)
* Anemia
* Alcohol or drug abuse
* Smoking
* Medication exclusions will include steroids as well as statins and other medications with anti-inflammatory actions
* Women who have received a typhoid vaccine within the last three years","healthyVolunteers":false,"sex":"FEMALE","minimumAge":"35 Years","maximumAge":"80 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"overallOfficials":[{"name":"Janice Kiecolt-Glaser, PhD","affiliation":"Arthur G. James Cancer Hospital and Solove Research Institute at Ohio State University Wexner Medical Center","role":"PRINCIPAL_INVESTIGATOR"}],"locations":[{"facility":"Arthur G. James Cancer Hospital and Solove Research Institute at Ohio State University Wexner Medical Center","city":"Columbus","state":"Ohio","zip":"43210","country":"United States","geoPoint":{"lat":39.96118,"lon":-82.99879}}]},"referencesModule":{"references":[{"pmid":"36943254","type":"DERIVED","citation":"Madison AA, Renna M, Andridge R, Peng J, Shrout MR, Sheridan J, Lustberg M, Ramaswamy B, Wesolowski R, Williams NO, Noonan AM, Reinbolt RE, Stover DG, Cherian MA, Malarkey WB, Kiecolt-Glaser JK. Conflicts hurt: social stress predicts elevated pain and sadness after mild inflammatory increases. Pain. 2023 Sep 1;164(9):1985-1994. doi: 10.1097/j.pain.0000000000002894. Epub 2023 Mar 22."}],"seeAlsoLinks":[{"label":"The Jamesline","url":"http://cancer.osu.edu"}]},"ipdSharingStatementModule":{"ipdSharing":"NO"}},"resultsSection":{"participantFlowModule":{"groups":[{"id":"FG000","title":"Arm I (Placebo/Vaccine)","description":"Patients receive placebo IM at visit 1 followed by inactive typhoid vaccine IM 30 days later at visit 2.

